n=22; g=[[5]*n for _ in range(n)]
def tile(top,left,frame,fill):
    for dr in range(5):
        for dc in range(5):
            g[top+dr][left+dc] = fill if 1<=dr<=3 and 1<=dc<=3 else frame
for y,x,f,c in [(3,0,8,9),(12,5,8,1),(16,0,8,2),(5,17,2,4),(9,17,2,3),(17,17,2,9)]: tile(y,x,f,c)
print('\n'.join(' '.join(map(str,r)) for r in g))

g2=[[5]*22 for _ in range(22)]
def put(y,x,b,c):
    for dy in range(5):
        for dx in range(5): g2[y+dy][x+dx]=c if 1<=dy<=3 and 1<=dx<=3 else b
for y,x,b,c in [(3,0,8,9),(12,5,8,1),(16,0,8,2),(5,17,2,4),(9,12,2,3),(17,17,2,9)]: put(y,x,b,c)
print('\n'.join('['+','.join(map(str,r))+'],' for r in g2))
